fn is_prime(n: i8) -> bool {
    // Handle edge cases: numbers less than 2 are not prime
    if n < 2 {
        return false;
    }
    
    // Check divisors from 2 to n-1
    for k in 2..n {
        if n % k == 0 {
            return false;  // Found a divisor, not prime
        }
    }
    
    // No divisors found, number is prime
    true
}